  'http.client.HTTPConnection\n'
  '        connection = connection_type(url.hostname, url.port, '
  'timeout=self.config.request_timeout)\n'
  '        outgoing = {"x-api-key": self.config.api_key}\n'
  '        outgoing.update(headers or {})\n'
  '        if json is not None:\n'
  '            data = jsonlib.dumps(json).encode("utf-8")\n'
  '            outgoing["Content-Type"] = "application/json"\n'
  '        if isinstance(data, Multipart):\n'
  '            outgoing["Content-Length"] = str(data.length)\n'
  '        elif data is not None:\n'
  '            outgoing["Content-Length"] = str(len(data))\n'
