  'headers=outgoing)\n'
  '            response = connection.getresponse()\n'
  '            self.log("API status " + str(response.status))\n'
  '            if not 200 <= response.status < 300:\n'
  '                detail = server_message(response.read(64 * 1024))\n'
  '                raise HttpFailure(response.status, "Immich HTTP " + str(response.status) + ": " '
  '+ method + " " + path\n'
  '                                  + (" (" + detail + ")" if detail else ""))\n'
  '            body = response.read(16 * 1024 * 1024 + 1)\n'
  '            if len(body) > 16 * 1024 * 1024:\n'
  '                raise ImportFailure("Immich JSON response exceeds size limit")\n'
  '            if response.status == 204 or not body:\n'
  '                return None\n'
  '            try:\n'
  '                return jsonlib.loads(body)\n'
  '            except (ValueError, UnicodeError):\n'
  '                raise ImportFailure("Immich returned invalid JSON: " + path) from None\n'
