  'account")\n'
  '        elif user.get("name") != self.config.expected_user_name:\n'
  '            raise ImportFailure("Immich user is not the configured Camera Archive account")\n'
  '        self.owner_id = asset_id(user.get("id"))\n'
  '        media = self.request("GET", "/server/media-types")\n'
  '        if not isinstance(media, dict) or not isinstance(media.get("image"), list) or not '
  'isinstance(media.get("video"), list):\n'
  '            raise ImportFailure("Invalid supported media types response")\n'
  '        self.media_types = {str(x).lower() for x in media["image"] + media["video"]}\n'
  '\n'
  '    def check(self, items):\n'
  '        found = {}\n'
  '        for offset in range(0, len(items), 100):\n'
  '            batch = items[offset:offset + 100]\n'
  '            data = self.request("POST", "/assets/bulk-upload-check", json={"assets": [\n'
  '                {"id": str(index), "checksum": item.sha1} for index, item in '
  'enumerate(batch)]})\n'
