  '\n'
  '    def upload(self, item):\n'
  '        timestamp = datetime.fromtimestamp(item.fingerprint[3] / 1e9, '
  'timezone.utc).isoformat()\n'
  '        # These required transport timestamps are filesystem facts. Capture time\n'
  "        # extraction remains Immich's job; no timezone is guessed from filenames.\n"
  '        # Unknown hashes are computed from the very bytes being sent, so a new\n'
