  '"application/rdf+xml")\n'
  '            encoder = Multipart(fields, hasher.update if hasher else None)\n'
  '            try:\n'
  '                response = self.request("POST", "/assets", data=encoder,\n'
  '                                        headers={"Content-Type": encoder.content_type})\n'
  '            finally:\n'
  '                # Whatever the response, a fully streamed file yielded its hashes;\n'
  '                # the read-only guard above rejects a source changed meanwhile.\n'
