  '"duplicate"):\n'
  '            raise ImportFailure("Unrecognized Immich upload response")\n'
  '        return asset_id(response.get("id")), response["status"]\n'
  '\n'
  '    def stack(self, identifier):\n'
  '        value = self.request("GET", "/stacks/" + asset_id(identifier))\n'
  '        if not isinstance(value, dict) or not isinstance(value.get("assets"), list):\n'
  '            raise ImportFailure("Invalid stack response")\n'
  '        return value\n'
  '\n'
  '    def ensure_stack(self, primary, children):\n'
  '        """Group assets so the timeline shows only the primary. Returns the stack ID.\n'
  '\n'
  '        A stack already holding every member is accepted as it is. Stacks made\n'
  '        only of our members (an earlier partial import) are rebuilt with the\n'
  '        current primary; unstacking never deletes assets. A stack mixing our\n'
  '        members with foreign assets is a conflict left for review.\n'
  '        """\n'
