  '        existing = {}\n'
  '        for item in (primary, *children):\n'
  '            stack = self.info(item.asset_id).get("stack")\n'
  '            if stack is None:\n'
  '                continue\n'
  '            if not isinstance(stack, dict):\n'
  '                raise ImportFailure("Invalid stack field in asset response")\n'
  '            stack_id = asset_id(stack.get("id"))\n'
