  'self.stack(stack_id)["assets"] if isinstance(a, dict)}\n'
  '        for stack_id, members in existing.items():\n'
  '            if set(wanted) <= members:\n'
  '                return stack_id\n'
  '        if any(not members <= set(wanted) for members in existing.values()):\n'
  '            raise ImportFailure("STACK CONFLICT: a member already belongs to a stack with other '
  'assets")\n'
  '        for stack_id in existing:\n'
  '            self.request("DELETE", "/stacks/" + stack_id)\n'
  '        response = self.request("POST", "/stacks", json={"assetIds": wanted})\n'
  '        if not isinstance(response, dict):\n'
  '            raise ImportFailure("Invalid stack creation response")\n'
  '        stack_id = asset_id(response.get("id"))\n'
  '        stack = self.stack(stack_id)\n'
  '        members = {asset_id(a.get("id")) for a in stack["assets"] if isinstance(a, dict)}\n'
  '        if stack.get("primaryAssetId") != primary.asset_id or not set(wanted) <= members:\n'
  '            raise ImportFailure("Stack verification failed: " + primary.relative)\n'
  '        return stack_id\n'
  '\n'
  '    def info(self, identifier):\n'
  '        value = self.request("GET", "/assets/" + asset_id(identifier))\n'
  '        if not isinstance(value, dict):\n'
  '            raise ImportFailure("Invalid asset info response")\n'
  '        return value\n'
  '\n'
  '    def validate_identity(self, item, info):\n'
  '        try:\n'
  '            checksum = base64.b64decode(info["checksum"], validate=True).hex()\n'
  '        except (KeyError, ValueError, TypeError):\n'
  '            raise ImportFailure("Invalid checksum in asset response") from None\n'
  '        if info.get("id") != item.asset_id or info.get("ownerId") != self.owner_id or checksum '
  '!= item.sha1:\n'
  '            raise ImportFailure("Asset ID / owner / checksum mismatch")\n'
  '        if info.get("isTrashed") is not False or info.get("isOffline") is not False:\n'
  '            raise ImportFailure("Asset is trashed, offline, or availability is unverified")\n'
  '        if "libraryId" not in info or info["libraryId"] is not None:\n'
  '            raise ImportFailure("Asset is not a confirmed managed-library asset")\n'
  '\n'
  '    def verify(self, item, metadata=True):\n'
