  '        if info.get("visibility") != item.route:\n'
  '            self.request("PUT", "/assets/" + item.asset_id, json={"visibility": item.route})\n'
  '            info = self.info(item.asset_id)\n'
  '            self.validate_identity(item, info)\n'
  '            if info.get("visibility") != item.route:\n'
  '                raise ImportFailure("Visibility verification failed")\n'
  '        if not metadata:\n'
