  '"refresh-metadata"})\n'
  '        except HttpFailure as error:\n'
  '            if error.status != 403:\n'
  '                raise\n'
  '            warning = "Metadata refresh not permitted (API key lacks job.create); verified '
  'Immich\'s own extraction instead"\n'
  '            if warning not in self.warnings:\n'
  '                self.warnings.append(warning)\n'
  '            self.log(item.relative + ": " + str(error))\n'
  '        deadline = time.monotonic() + self.config.verify_timeout\n'
  '        while True:\n'
  '            info = self.info(item.asset_id)\n'
  '            self.validate_identity(item, info)\n'
  '            exif = info.get("exifInfo") or {}\n'
  '            if info.get("visibility") == item.route and all(exif.get(k) == v for k, v in '
  'item.expected.items()):\n'
