  '        return value\n'
  '    except (OSError, ValueError):\n'
  '        raise ImportFailure("MANIFEST CONFLICT: cannot safely read existing manifest") from '
  'None\n'
  '\n'
  '\n'
  'def merge(previous, key, owner_id, server_url, members):\n'
  '    expected = {"schemaVersion": 1, "bundleKey": key, "camera": "Insta360 OneRS",\n'
  '                "ownerId": owner_id, "serverUrl": server_url}\n'
  '    value = dict(previous) if previous is not None else dict(expected, members=[])\n'
  '    for field, content in expected.items():\n'
  '        if field in value and value[field] != content:\n'
  '            raise ImportFailure("MANIFEST CONFLICT: " + key + " / " + field)\n'
  '        value[field] = content\n'
  '    existing = value.get("members")\n'
  '    if not isinstance(existing, list):\n'
  '        raise ImportFailure("MANIFEST CONFLICT: invalid members")\n'
  '    roles = {}\n'
  '    for row in existing:\n'
  '        if not isinstance(row, dict) or row.get("role") not in ("master-00", "master-10", '
