  '        incoming = {"filename": item.path.name, "role": item.role, "size": item.size,\n'
  '                    "sha256": item.sha256, "immichChecksum": item.sha1,\n'
  '                    "assetId": item.asset_id, "visibility": item.route}\n'
  '        old = roles.get(item.role, {})\n'
