  'def build_plan(source, config, log, progress=QUIET):\n'
  '    progress("Scanning " + str(source))\n'
  '    plan = scan(source)\n'
  '    if not plan.items and not plan.errors:\n'
  '        plan.errors.append("No files found; source cannot be reviewed as imported")\n'
  '    elif not any(i.route in ("timeline", "archive", "probe", "companion") for i in '
  'plan.items):\n'
  '        plan.errors.append("No preservable camera media found; ignored files alone do not '
  'establish an archive")\n'
  '    targets = []\n'
  '    for item in plan.items:\n'
  '        log(item.relative + ": " + item.route + " (" + item.reason + ")")\n'
  '        if item.error:\n'
  '            item.status = "failed"\n'
  '        elif item.route in ("timeline", "probe"):\n'
  '            targets.append(item)\n'
  '    progress("Scanned " + str(len(plan.items)) + " files (" + str(len(plan.unknown)) + " '
  'unknown); reading camera metadata for "\n'
  '             + str(len(targets)) + " with " + config.exiftool_bin)\n'
  '    done = 0\n'
  '    for offset in range(0, len(targets), BATCH):\n'
  '        chunk = targets[offset:offset + BATCH]\n'
  '        try:\n'
  '            tags_by_path = probe_batch([i.path for i in chunk], config.exiftool_bin)\n'
  '        except ImportFailure as error:\n'
  '            log(str(error))\n'
  '            tags_by_path = {}\n'
  '        for item in chunk:\n'
  '            done += 1\n'
  '            progress("[" + str(done) + "/" + str(len(targets)) + "] metadata: " + '
  'item.relative)\n'
  '            try:\n'
  '                prepare_metadata(item, config.exiftool_bin, tags_by_path.get(item.path))\n'
  '            except (ImportFailure, OSError, ValueError) as error:\n'
  '                fail(item, error)\n'
  '                if item.route == "probe":\n'
  '                    item.route, item.reason = "unknown", "Photo metadata requires review"\n'
  '    return plan\n'
  '\n'
  '\n'
  'def summarize(plan, config, dry_run, metadata_verify, manifests=0, warnings=()):\n'
  '    errors = list(plan.errors)\n'
  '    errors.extend(i.relative + ": " + i.error for i in plan.items if i.error)\n'
  '    if plan.unknown:\n'
  '        errors.append("UNKNOWN FILES: " + str(len(plan.unknown)))\n'
  '    if plan.incomplete:\n'
  '        errors.append("INCOMPLETE 360 BUNDLE: " + str(len(plan.incomplete)))\n'
  '    if not metadata_verify:\n'
  '        errors.append("Metadata verification disabled; debug runs cannot establish safety")\n'
  '    if not dry_run:\n'
  '        for item in plan.items:\n'
  '            if item.route in ("timeline", "companion") and item.status == "planned":\n'
  '                errors.append("NOT PROCESSED: " + item.relative)\n'
  '    success = not errors\n'
  '    routes = {}\n'
  '    for route in ("timeline", "companion"):\n'
  '        counts = Counter(i.status for i in plan.items if i.route == route)\n'
  '        routes[route] = dict(counts)\n'
  '    return {"schemaVersion": 1, "source": str(plan.source), "dryRun": dry_run, "config": '
  'describe(config),\n'
  '            "result": ("DRY RUN OK" if dry_run else "SAFE TO REVIEW FOR CARD FORMAT") if '
  'success else "NOT SAFE TO FORMAT SOURCE",\n'
  '            "exitCode": 0 if success else 1, "counts": routes,\n'
  '            "hashSources": dict(Counter(i.hash_source for i in plan.items if i.hash_source)),\n'
  '            "cameraMetadata": {"verified": sum(i.verified for i in plan.assets),\n'
  '                               "failed": sum(i.status == "failed" for i in plan.assets),\n'
  '                               "xmpPrepared": sum(i.xmp is not None for i in plan.assets)},\n'
  '            "bundles": {"complete": len(plan.bundles) - len(set(plan.incomplete) | '
  'set(plan.lrv_missing)),\n'
  '                        "lrvMissing": list(plan.lrv_missing), "incomplete": plan.incomplete,\n'
  '                        "manifestsWrittenOrVerified": manifests},\n'
  '            "ignored": dict(Counter(i.reason for i in plan.items if i.route == "ignored")),\n'
  '            "skippedDirectories": list(plan.skipped),\n'
  '            "stacks": {key: [m.relative for m in members] for key, members in '
  'plan.stacks.items()},\n'
  '            "unknown": [i.relative for i in plan.unknown], "errors": errors, "warnings": '
  'list(warnings),\n'
  '            "items": [i.public() for i in plan.items]}\n'
  '\n'
  '\n'
  'def tool_version(executable, flag):\n'
  '    try:\n'
  '        result = subprocess.run([executable, flag], stdout=subprocess.PIPE, '
  'stderr=subprocess.PIPE, timeout=60)\n'
  '    except (OSError, subprocess.TimeoutExpired):\n'
  '        raise ImportFailure("not runnable: " + executable) from None\n'
  '    if result.returncode:\n'
  '        raise ImportFailure("exited with status " + str(result.returncode) + ": " + '
  'executable)\n'
  '    output = (result.stdout or b"").decode("utf-8", "replace").strip()\n'
  '    return output.splitlines()[0] if output else "ok"\n'
  '\n'
  '\n'
  'def describe_root(path):\n'
  '    if path.is_symlink():\n'
  '        raise ImportFailure("symlink is not allowed: " + str(path))\n'
  '    if path.is_dir():\n'
  '        if not os.access(path, os.W_OK | os.X_OK):\n'
  '            raise ImportFailure("exists but is not writable: " + str(path))\n'
  '        return "exists, writable"\n'
  '    if path.exists():\n'
  '        raise ImportFailure("exists but is not a directory: " + str(path))\n'
  '    parent = path\n'
  '    while not parent.exists():\n'
  '        parent = parent.parent\n'
  '    if not os.access(parent, os.W_OK | os.X_OK):\n'
  '        raise ImportFailure("cannot be created; " + str(parent) + " is not writable")\n'
  '    return "will be created under " + str(parent)\n'
  '\n'
  '\n'
  'def check_config(source, config, log=QUIET, api_factory=Immich):\n'
  '    """Validate configuration, tools and Immich access without touching media or outputs."""\n'
  '    checks = []\n'
  '\n'
  '    def check(name, action):\n'
  '        try:\n'
  '            detail = action()\n'
  '            checks.append({"name": name, "status": "ok", "detail": detail})\n'
  '            return True\n'
  '        except (ImportFailure, OSError, ValueError) as error:\n'
  '            checks.append({"name": name, "status": "failed", "detail": str(error)})\n'
  '            return False\n'
  '\n'
  '    check("output roots do not overlap source or Immich storage",\n'
  '          lambda: (validate_roots(source, config.companion_root, config.manifest_root), '
  '"ok")[1])\n'
  '    check("companion_root " + str(config.companion_root), lambda: '
  'describe_root(config.companion_root))\n'
  '    check("manifest_root " + str(config.manifest_root), lambda: '
  'describe_root(config.manifest_root))\n'
  '    check("exiftool " + config.exiftool_bin, lambda: "version " + '
  'tool_version(config.exiftool_bin, "-ver"))\n'
  '    check("immich CLI " + config.immich_bin, lambda: "version " + '
  'tool_version(config.immich_bin, "--version"))\n'
  '    if check("Immich credentials", lambda: (authenticate(config), "API " + '
  'config.api_url)[1]):\n'
  '        def preflight():\n'
  '            api = api_factory(config, log)\n'
  '            try:\n'
  '                api.preflight()\n'
  '                return "server 3.1.0, account " + config.expected_user_name + " (" + '
  'api.owner_id + "), " + str(len(api.media_types)) + " media types"\n'
  '            finally:\n'
  '                api.close()\n'
  '        check("Immich server, account and permissions", preflight)\n'
  '    ok = all(c["status"] == "ok" for c in checks)\n'
  '    return {"schemaVersion": 1, "source": str(source), "config": describe(config), "checks": '
  'checks,\n'
  '            "result": "CONFIG OK" if ok else "CONFIG INVALID", "exitCode": 0 if ok else 1,\n'
  '            "errors": [c["name"] + ": " + c["detail"] for c in checks if c["status"] != "ok"]}\n'
  '\n'
  '\n'
  'def execute(source, config, dry_run=False, strict=False, metadata_verify=True,\n'
  '            log=QUIET, api_factory=Immich, progress=QUIET):\n'
  '    validate_roots(source, config.companion_root, config.manifest_root)\n'
  '    api = None\n'
  '    try:\n'
  '        if not dry_run:\n'
