  '                        item.verified = True\n'
  '                        log(item.relative + ": " + item.status)\n'
  '                    except (OSError, ImportFailure) as error:\n'
  '                        fail(item, error)\n'
  '            pending = [i for i in plan.assets if not i.error]\n'
  '            known = [i for i in pending if i.sha1]\n'
  '            try:\n'
  '                existing = api.check(known) if known else {}\n'
  '            except ImportFailure as error:\n'
  '                existing = {}\n'
  '                for item in known:\n'
  '                    fail(item, error)\n'
  '            # Avoid redundant sends for repeated identical source copies.\n'
  '            resolved = {}\n'
  '            for position, item in enumerate(pending, 1):\n'
  '                if item.error:\n'
  '                    continue\n'
  '                action = "verify" if item.relative in existing else "upload+hash" if not '
  'item.sha1 else "upload"\n'
  '                progress("[" + str(position) + "/" + str(len(pending)) + "] " + action + ": " + '
  'item.relative)\n'
  '                try:\n'
