  '                            raise ImportFailure("Matching asset is in the trash")\n'
  '                        item.status = "already_present"\n'
  '                    elif item.sha1 and item.sha1 in resolved:\n'
  '                        item.asset_id, item.status = resolved[item.sha1], "already_present"\n'
  '                    else:\n'
  '                        item.asset_id, status = api.upload(item)\n'
  '                        item.status = "uploaded" if status == "created" else "already_present"\n'
  '                        log(item.relative + " SHA-256 " + item.sha256)\n'
  '                    resolved[item.sha1] = item.asset_id\n'
  '                    api.verify(item, metadata_verify)\n'
  '                    log(item.relative + ": " + item.status)\n'
  '                except (OSError, ImportFailure) as error:\n'
  '                    fail(item, error)\n'
  '                finally:\n'
  '                    # Whatever the outcome, the hash is a fact about the bytes.\n'
  '                    hashcache.record(index, item, now)\n'
  '            identity_checks()\n'
  '            for item in plan.items:\n'
  '                if item.route == "companion":\n'
  '                    hashcache.record(index, item, now)\n'
  '            try:\n'
  '                hashcache.save(config.manifest_root, index, now)\n'
  '            except (OSError, ImportFailure):\n'
  '                plan.errors.append("Failed to persist hash index")\n'
  '            for key, members in plan.stacks.items():\n'
  '                if any(m.error or not m.asset_id for m in members):\n'
  '                    continue\n'
