  '                        manifest.save(config.manifest_root, key, api.owner_id, config.api_url, '
  'members)\n'
  '                        written += 1\n'
  '                except (OSError, ImportFailure) as error:\n'
  '                    plan.errors.append(str(error))\n'
  '            # Catch source changes affecting even ignored files or old assets.\n'
  '            for item in plan.items:\n'
  '                if item.fingerprint is not None:\n'
  '                    try:\n'
  '                        message = changed(item.path, item.fingerprint)\n'
  '                        if message:\n'
  '                            raise ImportFailure(message)\n'
  '                    except (OSError, ImportFailure) as error:\n'
  '                        fail(item, error)\n'
