  '\n'
  '\n'
  'def parser():\n'
  '    p = argparse.ArgumentParser(description="Read-only DJI Pocket 3 / Insta360 ONE RS import '
  'into Immich 3.1.0")\n'
  '    p.add_argument("path", nargs="?", default=".")\n'
  '    p.add_argument("--version", action="version", version=__version__)\n'
  '    p.add_argument("--dry-run", action="store_true", help="Plan locally; no API calls or '
  'persistent writes")\n'
  '    p.add_argument("--verbose", action="store_true", help="Diagnostic progress on stderr; never '
  'log credentials")\n'
  '    p.add_argument("--quiet", action="store_true", help="No progress lines on stderr")\n'
  '    p.add_argument("--json", action="store_true", help="Exactly one JSON report on stdout")\n'
  '    p.add_argument("--check-config", action="store_true", help="Validate configuration, tools '
  'and Immich access; touches no media")\n'
  '    p.add_argument("--strict", action="store_true", help="Abort before writes when planning '
  'finds any issue")\n'
  '    p.add_argument("--no-metadata-verify", action="store_true", help="Debug only; always '
